1	//! Budgeted offline staging behind the [`StagingStore`] seam (blueprint/
2	//! engine.md "Sync core: Ops"; #33 D6).
3	//!
4	//! Web reaches full offline parity: uploads stage into OPFS/IndexedDB behind
5	//! the profile budget; **past the budget only new uploads fail fast, while
6	//! metadata ops queue unbounded**. The op queue is the durable divergence and
7	//! must never be capped — a delete or rename can always be journaled — but
8	//! staged upload *bytes* are bounded so an offline device cannot exhaust host
9	//! storage.
10	
11	use crate::profile::SyncTimingProfile;
12	use crate::seams::{OpId, SeamError, SeamResult, StagingStore};
13	use crate::sync::op::Op;
14	
15	/// The outcome of staging one op.
16	#[derive(Debug, Clone, PartialEq, Eq)]
17	pub enum StageOutcome {
18	    /// The op was journaled; on a content op its bytes were staged too.
19	    Queued {
20	        /// The durable op-queue id.
21	        op_id: OpId,
22	    },
23	    /// A content upload would exceed the profile staging budget: it fails fast
24	    /// and **nothing** is journaled or staged (the mutation did not happen).
25	    RejectedOverBudget {
26	        /// Staged bytes already held.
27	        staged: u64,
28	        /// The upload's own byte length.
29	        incoming: u64,
30	        /// The profile budget.
31	        budget: u64,
32	    },
33	}
34	
35	/// Stage one op. Metadata ops (no upload bytes) always enqueue, regardless of
36	/// budget. A content op is fail-fast: if staged-total + its bytes would exceed
37	/// the budget, nothing is written; otherwise the bytes are staged under the
38	/// op's staging key and the op is enqueued.
39	///
40	/// `upload` is the **already-sealed** content payload (core's content-seal runs
41	/// upstream in the content plane); no plaintext user content ever lands in the
42	/// staging store at rest.
43	///
44	/// Fail-fast ordering: the budget is checked and the bytes staged **before**
45	/// the op is enqueued, so a rejected upload leaves no dangling queue entry and
46	/// an accepted one leaves no op referencing unstaged bytes.
47	pub async fn stage_op<S: StagingStore>(
48	    store: &S,
49	    profile: &SyncTimingProfile,
50	    op: &Op,
51	    upload: Option<&[u8]>,
52	) -> SeamResult<StageOutcome> {
53	    match (op.staging_key(), upload) {
54	        (Some(key), Some(bytes)) => {
55	            let staged = store.staged_bytes_total().await?;
56	            let incoming = bytes.len() as u64;
57	            // Saturating: an overflowing sum is unreachable under any real
58	            // budget, and must still read as "over budget", never wrap to a
59	            // spuriously-small total.
60	            if staged.saturating_add(incoming) > profile.staging_budget_bytes {
61	                return Ok(StageOutcome::RejectedOverBudget {
62	                    staged,
63	                    incoming,
64	                    budget: profile.staging_budget_bytes,
65	                });
66	            }
67	            store.put_staged_bytes(key, bytes).await?;
68	            let op_id = store.enqueue_op(&op.encode()).await?;
69	            Ok(StageOutcome::Queued { op_id })
70	        }
71	        // A content op (staging key present) with no bytes is a broken caller
72	        // contract: journaling it would leave a durable op referencing content
73	        // that was never staged. Fail closed — enqueue nothing.
74	        (Some(_), None) => Err(SeamError::new(
75	            "stage_op: content op carries a staging key but no upload bytes",
76	        )),
77	        // A metadata op (no staging key): journal unbounded.
78	        (None, _) => {
79	            let op_id = store.enqueue_op(&op.encode()).await?;
80	            Ok(StageOutcome::Queued { op_id })
81	        }
82	    }
83	}
84	
85	/// Staging keys held by the store that no queued op references — orphan
86	/// residue from a rejected or superseded upload, safe to GC (#33 D6 staged-
87	/// bytes hygiene).
88	pub async fn orphan_staging_keys<S: StagingStore>(store: &S) -> SeamResult<Vec<Vec<u8>>> {
89	    let queued = store.queued_ops().await?;
90	    let mut referenced = std::collections::HashSet::new();
91	    for (_, bytes) in &queued {
92	        match Op::decode(bytes) {
93	            Ok(op) => {
94	                if let Some(key) = op.staging_key() {
95	                    referenced.insert(key.to_vec());
96	                }
97	            }
98	            // An undecodable entry dead-letters with its staged bytes preserved
99	            // (#33 D6); its staging key is unknowable, so nothing is safely an
100	            // orphan this pass — fail closed.
101	            Err(_) => return Ok(Vec::new()),
102	        }
103	    }
104	    let orphans = store
105	        .staged_keys()
106	        .await?
107	        .into_iter()
108	        .filter(|key| !referenced.contains(key))
109	        .collect();
110	    Ok(orphans)
111	}
